const intro=document.querySelector('.cinema-intro'),brew=document.querySelector('.brew-journey'),header=document.querySelector('header'),card=document.querySelector('.manifesto');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const clamp=n=>Math.max(0,Math.min(1,n));let pending=false;const phases=[['Start with something good.','Carefully brewed coffee. A warm ceramic cup. The first moment of a slower day.'],['Let the world wait.','Take a breath. Follow the mountain light. Some moments deserve your full attention.'],['Stay a little longer.','One more sip, one more story. Find your favourite and make yourself at home.']];let phase=-1;
function update(){pending=false;const i=intro.getBoundingClientRect(),b=brew.getBoundingClientRect(),ip=reduced?0:clamp(-i.top/(intro.offsetHeight-innerHeight)),bp=reduced?0:clamp(-b.top/(brew.offsetHeight-innerHeight));intro.style.setProperty('--intro-progress',ip);intro.style.setProperty('--zoom',1.05+ip*.38);intro.style.setProperty('--title-y',`${-ip*150}px`);intro.style.setProperty('--title-opacity',clamp(1-ip*3));const show=clamp((ip-.23)*3.2);intro.style.setProperty('--card-opacity',show);intro.style.setProperty('--card-y',`${(1-show)*100}px`);card.classList.toggle('shown',show>.6);card.inert=show<.6;brew.style.setProperty('--brew-progress',bp);window.dispatchEvent(new CustomEvent('brewprogress',{detail:bp}));const darkSurface=[document.querySelector('.quote'),document.querySelector('#visit')].some(s=>{const r=s.getBoundingClientRect();return r.top<60&&r.bottom>60});header.classList.toggle('dark-nav',i.bottom<80&&!darkSurface);const current=Math.min(2,Math.floor(bp*3));if(current!==phase){phase=current;document.querySelector('#brew-title').textContent=phases[current][0];document.querySelector('#brew-description').textContent=phases[current][1];document.querySelector('.brew-number').textContent=`0${current+1} — 03`} }
addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(update)}},{passive:true});addEventListener('resize',update);intro.addEventListener('pointermove',e=>{if(reduced||e.pointerType!=='mouse')return;intro.style.setProperty('--pan-x',`${(e.clientX/innerWidth-.5)*-14}px`);intro.style.setProperty('--pan-y',`${(e.clientY/innerHeight-.5)*-10}px`)});intro.addEventListener('pointerleave',()=>{intro.style.setProperty('--pan-x','0px');intro.style.setProperty('--pan-y','0px')});const sectionObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){const link=header.querySelector(`a[href="#${e.target.id}"]`);if(link){header.querySelectorAll('nav a').forEach(a=>a.classList.remove('active'));link.classList.add('active')}}}),{rootMargin:'-20% 0px -55% 0px'});document.querySelectorAll('main section[id]').forEach(s=>sectionObserver.observe(s));update();
